<?php require_once 'config.php'; $email=$_SESSION['reset_email']??''; if(!$email){header('Location: forgot_password.php');exit;} $error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $otp=trim($_POST['otp']??'');$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
 $q=mysqli_prepare($conn,'SELECT id FROM users WHERE email=? AND reset_otp=? AND reset_otp_expires>=NOW() LIMIT 1'); mysqli_stmt_bind_param($q,'ss',$email,$otp); mysqli_stmt_execute($q); $u=mysqli_fetch_assoc(mysqli_stmt_get_result($q));
 if(!$u) $error='Invalid or expired OTP.'; elseif(strlen($pass)<6) $error='Password must be at least 6 characters.'; elseif($pass!==$confirm) $error='Passwords do not match.'; else { $hash=password_hash($pass,PASSWORD_DEFAULT); $q=mysqli_prepare($conn,'UPDATE users SET password=?,reset_otp=NULL,reset_otp_expires=NULL WHERE id=?'); mysqli_stmt_bind_param($q,'si',$hash,$u['id']); mysqli_stmt_execute($q); unset($_SESSION['reset_email']); $success='Password changed successfully. OTP is now used.'; }
}
?><!doctype html><html><head><title>Reset Password</title><link rel="stylesheet" href="assets/css/root/reset_password.css"></head><body><div class="box"><h1>🔑 Reset Password</h1><p>OTP sent to <?=e($email)?></p><?php if($error): ?><div class="error"><?=e($error)?></div><?php endif; ?><?php if($success): ?><div class="success"><?=e($success)?></div><a href="index.php">Login</a><?php else: ?><form method="post"><input name="otp" placeholder="6 Digit OTP" maxlength="6" required><input type="password" name="password" placeholder="New Password" required><input type="password" name="confirm_password" placeholder="Confirm Password" required><button>Reset Password</button></form><?php endif; ?></div></body></html>
